func approvalDecision(a *itemApproval) string {
	if a == nil {
		return ""
	}
	return a.Decision
}

func questionState(it store.Item, a *itemApproval) string {
	switch {
	case a == nil && it.Status == domain.ItemRunning:
		return "waiting for your answer"
	case a != nil && a.Decision == domain.DecisionDeny:
		return "skipped"
	}
	return "not answered"
}

func approveURL(a store.Approval, decision string) string {
	return "@post('/api/threads/" + a.ThreadID + "/approvals/" + a.ID + "/" + decision + "')"
}

func decisionLabel(d string) string {
	switch d {
	case domain.DecisionAllow:
		return "allowed"
	case domain.DecisionAllowSession:
		return "allowed for session"
	case domain.DecisionDeny:
		return "denied"
	}
	return d
}

func firstLine(s string) string {
	for i, r := range s {
		if r == '\n' {
			return s[:i]
		}
		if i > 120 {
			return s[:i] + "…"
		}
	}
	return s
}

func clip(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "\n… (truncated)"
}

